/**
 * @file levels/desert.hpp
 *
 * Sand Tristram: a desert camp of tents and makeshift huts, reached by caravan from Tristram,
 * with its own tileset (assets/levels/desertdata, generated by tools/desert/gen_desert.py).
 * The camp is a town level (DTYPE_TOWN) drawn with the desert tiles; beyond it lie the Desert
 * Wastes, the Darkwood's endless waves painted in sand and stone. Single player only.
 */
#pragma once

#include <cstdint>
#include <optional>
#include <span>
#include <string_view>

#include "engine/point.hpp"
#include "levels/gendung_defs.hpp"

namespace devilution {

/** @brief The hero is in Sand Tristram or the wastes beyond it (decides town and tileset). */
[[nodiscard]] bool InDesertRegion();
void SetInDesertRegion(bool inDesert);

/** @brief Desert travel exists (single player only). */
[[nodiscard]] bool IsDesertAvailable();

/** @brief Set slot used to save the items lying around Sand Tristram (separate from Tristram's). */
constexpr uint8_t DesertTownSaveSlot = 15;

// --- Caravan ---------------------------------------------------------------------------------

/** @brief Travel by caravan to Sand Tristram (toDesert) or back to Tristram. */
void TravelByCaravan(bool toDesert);

/** @brief The hero arrived by caravan: place them next to the caravan instead of the default spot. */
[[nodiscard]] bool ArrivingByCaravan();
void ClearCaravanArrival();

/** @brief Where the caravan stands in Tristram (by the cows) and where its passengers step off. */
inline constexpr Point TristramCaravanArrival { 63, 23 };

// --- Tileset ---------------------------------------------------------------------------------

/** @brief Paths of the desert tileset files. */
inline constexpr std::string_view DesertCelPath = "levels\\desertdata\\desert.cel";
inline constexpr std::string_view DesertMinPath = "levels\\desertdata\\desert.min";
inline constexpr std::string_view DesertSolPath = "levels\\desertdata\\desert.sol";
inline constexpr std::string_view DesertTilPath = "levels\\desertdata\\desert.til";

struct DesertStructure {
	int width = 0;
	int height = 0;
	std::span<const uint16_t> pieces; // row-major, width * height
};

/** @brief A named piece group from txtdata\desert\pieces.tsv (empty if unknown). */
DesertStructure GetDesertStructure(std::string_view name);

/** @brief All piece groups of a category (floor, floordetail, rock, pillar, tree...). */
std::span<const DesertStructure> GetDesertCategory(std::string_view category);

// --- Sand Tristram ---------------------------------------------------------------------------

void CreateDesertTown(lvl_entry entry);
void InitDesertTownTriggers();
bool ForceDesertTownTrig();
/** @brief Where the hero steps back into camp when leaving the wastes. */
[[nodiscard]] Point DesertWastesReturnPosition();

// --- Desert Wastes ---------------------------------------------------------------------------

/** @brief Paints the wastes: cells is a grid of 56x56 megacells, 0 = rock, 1 = open, 2 = trail. */
void PaintDesertWastes(const uint8_t (&cells)[56][56], uint32_t seed);

} // namespace devilution
